trait Mapper[A, B] { def map(a: A): B }

given Mapper[UserDto, User] with                    // the mapper, in one instance
  def map(d: UserDto) = User(d.id, d.fullName, d.isAdmin.getOrElse(false))

extension [A](a: A) def to[B](using m: Mapper[A, B]): B = m.map(a)
// val user: User = dto.to[User]

object User {                                      // the mapper, one object per pair
  def fromDto(d: UserDto): User =
    User(d.id, d.fullName, d.isAdmin.getOrElse(false))
  def toDto(u: User): UserDto =
    UserDto(u.id, u.name, Some(u.isAdmin))
}
